s=s[:a]+'''/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply descending from it (directly or through
 * other replies) in order of posting. A deleted comment keeps its place as a
 * placeholder without its text, so the replies below it stay where they were.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt), asc(comments.id))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => {
    const comment = { ...toComment(row.comment), author: toUser(row.author) };
    return comment.archivedAt === null
      ? comment
      : { ...comment, body: "", mentionedUserIds: [] };
  });

  const byId = new Map<string, CommentWithAuthor>();
  for (const comment of decorated) byId.set(comment.id, comment);

  const rootOf = (comment: CommentWithAuthor): CommentWithAuthor | null => {
    const visited = new Set<string>();
    let current: CommentWithAuthor | undefined = comment;
    while (current && current.parentId !== null) {
      if (visited.has(current.id)) return null;
      visited.add(current.id);
      current = byId.get(current.parentId);
    }
    return current ?? null;
  };

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const root = rootOf(comment);
    if (root === null) continue;
    const bucket = repliesBy.get(root.id) ?? [];
    bucket.push(comment);
    repliesBy.set(root.id, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

